				// Сбрасываем id таймера
				id = undefined;
			},

			// Устанавливаем время задержки
			//
			// Тут вычитаем с нашей задержки время ожидания, минимально допустимое значение - 0
			// Поэтому при первом вызове получится отрицательное число, которое приведётся к нулю,
			// так как wait будет равен текущему времени, и вызов произойдёт с нулевой задержкой.
			//
			// После чего в переменной ms, уже будет время вызова
			// и следующий таймер будет установлен на разницу времени задержки
			// и времени ожидания с предыдущего выполнения.
			//
			// В итоге получится интервал выполнении практически равен времени задержки,
			// с момента предыдущего выполнения.
			// ( погрешность несколько ms, в зависимости от браузера )...
			Math.max( 0, delay - wait )
		);
	};
